const e = $input.first().json;
const wf = (e.workflow && e.workflow.name) || 'unknown workflow';
const node = (e.execution && e.execution.lastNodeExecuted) || 'unknown node';
const msg = (e.execution && e.execution.error && e.execution.error.message) || 'no message';
return [{ json: { subject: 'FAILED: ' + wf, body: 'Node: ' + node + '\nError: ' + msg + '\nExecution: ' + (e.execution && e.execution.id) + '\nFirst move: check whether the record was written before the failure.' } }];

// In production this node is your Gmail or Slack node from
// Lesson 15, fed by the alert fields above. It is a Code node
// here so the error workflow imports with zero credentials.
return $input.all();
